/** Composition for a 1-based wave number (past 40: back by 20, as the ROM does). */
export function getWaveDef(wave: number): WaveDef {
    let w = Math.max(1, wave);
    while (w > 40) w -= 20;
    return WAVES[w - 1];
}

/** Humans on a wave (mommies + daddies + mikeys). */
export function humanCount(def: WaveDef): number {
    return def.mommies + def.daddies + def.mikeys;
}
